struct Pair<T> {
    a: T;
    b: T;
}

impl<T> Pair<T> {
    fn first(&self) -> T { ret self.a; }

    fn swap(&mut self) {
        var t: T = self.a;
        self.a = self.b;
        self.b = t;
    }
}

fn max<T>(x: T, y: T) -> T {
    if x > y { ret x; }
    ret y;
}

