@import("std/std.mw")

// An owning pointer (^T) frees its memory when it goes out of scope.
// Handing it over empties the variable; a loan (&T) does not.

@trusted fn make(v: i64) -> ^i64 {
    var p: ^i64 = cast(^i64) alloc(8);
    *p = v;
    ret p;
}

fn peek(p: &i64) -> i64 { ret *p; }
fn bump(p: &mut i64) { *p += 1; }

fn take(p: ^i64) -> i64 {
    var v: i64 = *p;
    ret v;              // `p` is dropped here: the memory is freed
}

@trusted fn main() -> i32 {
    var a: ^i64 = make(10);
    println_i64(peek(a));   // a loan
    bump(a);
    println_i64(peek(a));
    var b: ^i64 = a;        // handed over: `a` is empty now
    println_i64(take(b));
    ret 0;
}

@import("std/std.mw")

fn is_prime(n: i64) -> bool {
    if n < 2 { ret false; }
    var d: i64 = 2;
    while d * d <= n {
        if n % d == 0 { ret false; }
        d += 1;
    }
    ret true;
}

fn main() -> i32 {
    var count: i64 = 0;
    for var n: i64 = 0; n < 200000; n += 1 {
        if is_prime(n) { count += 1; }
    }
    print("primes below 200000: ");
    println_i64(count);
    ret 0;
}
